// Sound effects and music, played with expo-audio. Every file is generated by tools/make_audio.ts.
// Sounds start off the render path (setTimeout 0) with a single play() call, and each player rewinds itself after
// its sound has finished, so no seek happens right before playing (that stalls on iOS). Music is three looping
// tracks that crossfade when the scene changes. Both follow the Sound and Music switches and pause in the background.
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { AppState, Platform } from 'react-native';
import type { ElementId } from '../game/data/elements';

/* eslint-disable @typescript-eslint/no-require-imports */
const SFX = {
  breed: require('../../assets/sfx/breed.wav'),
  buff: require('../../assets/sfx/buff.wav'),
  chest: require('../../assets/sfx/chest.wav'),
  coin: require('../../assets/sfx/coin.wav'),
  crack: require('../../assets/sfx/crack.wav'),
  crackBig: require('../../assets/sfx/crackBig.wav'),
  dark: require('../../assets/sfx/dark.wav'),
  debuff: require('../../assets/sfx/debuff.wav'),
  defeat: require('../../assets/sfx/defeat.wav'),
  egg: require('../../assets/sfx/egg.wav'),
  faint: require('../../assets/sfx/faint.wav'),
  fire: require('../../assets/sfx/fire.wav'),
  grow: require('../../assets/sfx/grow.wav'),
  hatch: require('../../assets/sfx/hatch.wav'),
  heal: require('../../assets/sfx/heal.wav'),
  hit: require('../../assets/sfx/hit.wav'),
  hitBig: require('../../assets/sfx/hitBig.wav'),
  ice: require('../../assets/sfx/ice.wav'),
  levelup: require('../../assets/sfx/levelup.wav'),
  magic: require('../../assets/sfx/magic.wav'),
  miss: require('../../assets/sfx/miss.wav'),
  nature: require('../../assets/sfx/nature.wav'),
  poof: require('../../assets/sfx/poof.wav'),
  reveal: require('../../assets/sfx/reveal.wav'),
  revive: require('../../assets/sfx/revive.wav'),
  roar: require('../../assets/sfx/roar.wav'),
  rock: require('../../assets/sfx/rock.wav'),
  select: require('../../assets/sfx/select.wav'),
  shield: require('../../assets/sfx/shield.wav'),
  star1: require('../../assets/sfx/star1.wav'),
  star2: require('../../assets/sfx/star2.wav'),
  star3: require('../../assets/sfx/star3.wav'),
  star4: require('../../assets/sfx/star4.wav'),
  star5: require('../../assets/sfx/star5.wav'),
  swing: require('../../assets/sfx/swing.wav'),
  tap: require('../../assets/sfx/tap.wav'),
  venom: require('../../assets/sfx/venom.wav'),
  victory: require('../../assets/sfx/victory.wav'),
  water: require('../../assets/sfx/water.wav'),
  zap: require('../../assets/sfx/zap.wav'),
};
const MUSIC = {
  hub: require('../../assets/music/hub.wav'),
  battle: require('../../assets/music/battle.wav'),
  boss: require('../../assets/music/boss.wav'),
};
/* eslint-enable @typescript-eslint/no-require-imports */

export type SfxName = keyof typeof SFX;
export type MusicName = keyof typeof MUSIC;

/** Relative loudness: the files are all normalized, so quiet UI sounds are turned down here. */
const VOL: Partial<Record<SfxName, number>> = {
  tap: 0.25, select: 0.35, coin: 0.4, hit: 0.75, hitBig: 0.9, miss: 0.5, swing: 0.5, crack: 0.8, crackBig: 0.9,
  heal: 0.55, buff: 0.5, debuff: 0.5, shield: 0.55, poof: 0.5, faint: 0.6, victory: 0.7, defeat: 0.7,
};
/** Voices per sound, for sounds that can overlap. */
const POOL: Partial<Record<SfxName, number>> = { hit: 4, hitBig: 2, tap: 3, crack: 2, poof: 3, swing: 3, miss: 2, heal: 2, buff: 2, debuff: 2 };
const MUSIC_VOL = 0.38;

let soundOn = true, musicOn = true;
let unlocked = Platform.OS !== 'web';
let active = AppState.currentState === 'active';
let modeSet = false;
function mode() {
  if (modeSet) return; modeSet = true;
  setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(() => {});
}

// ---------- effects
type Voice = { p: AudioPlayer; busyUntil: number };
const pools: Partial<Record<SfxName, Voice[]>> = {};
const LEN: Partial<Record<SfxName, number>> = {};
function pool(k: SfxName): Voice[] | undefined {
  if (!pools[k]) {
    try {
      mode();
      pools[k] = Array.from({ length: POOL[k] ?? 1 }, () => { const p = createAudioPlayer(SFX[k]); p.volume = VOL[k] ?? 0.7; return { p, busyUntil: 0 }; });
    } catch { return undefined; }
  }
  return pools[k];
}
/** Load the battle sounds ahead, so the first hit isn't late. */
export function preloadSfx() {
  for (const k of ['hit', 'hitBig', 'swing', 'miss', 'poof', 'faint', 'heal', 'buff', 'debuff', 'shield', 'fire', 'water', 'zap', 'ice', 'nature', 'magic', 'dark', 'venom', 'rock', 'roar', 'tap'] as SfxName[]) pool(k);
}

export function sfx(k: SfxName) {
  if (!soundOn || !unlocked) return;
  setTimeout(() => {
    const l = pool(k);
    if (!l) return;
    const t = Date.now();
    const v = l.find(x => x.busyUntil <= t);
    if (!v) return;
    const ms = Math.round(((v.p.duration || LEN[k] || 1.2)) * 1000) + 60;
    LEN[k] = v.p.duration || LEN[k];
    v.busyUntil = t + ms + 100;
    try { v.p.play(); } catch { return; }
    setTimeout(() => { try { v.p.pause(); v.p.seekTo(0).catch(() => {}); } catch {} }, ms);
  }, 0);
}

let lastTap = 0;
export function tap() {
  const t = Date.now();
  if (t - lastTap < 50) return;
  lastTap = t;
  sfx('tap');
}

/** The casting sound for a move's element. */
export function castSfx(el: ElementId): SfxName {
  switch (el) {
    case 'ember': return 'fire';
    case 'tide': return 'water';
    case 'spark': return 'zap';
    case 'frost': return 'ice';
    case 'verdant': case 'gale': case 'swarm': return 'nature';
    case 'mind': case 'glimmer': case 'radiant': case 'spirit': return 'magic';
    case 'shade': case 'void': return 'dark';
    case 'venom': return 'venom';
    case 'wyrm': return 'roar';
    default: return 'rock';
  }
}

// ---------- music
const decks: Partial<Record<MusicName, { p: AudioPlayer; vol: number }>> = {};
let want: MusicName | null = null;
let timer: ReturnType<typeof setInterval> | null = null;
const STEP = 50, FADE_MS = 900;

function deck(k: MusicName) {
  if (!decks[k]) {
    try { mode(); const p = createAudioPlayer(MUSIC[k]); p.loop = true; p.volume = 0; decks[k] = { p, vol: 0 }; } catch { return undefined; }
  }
  return decks[k];
}
function tick() {
  let moving = false;
  const step = (MUSIC_VOL * STEP) / FADE_MS;
  for (const k of Object.keys(MUSIC) as MusicName[]) {
    const goal = k === want && musicOn && active && unlocked ? MUSIC_VOL : 0;
    const d = goal > 0 ? deck(k) : decks[k];
    if (!d) continue;
    const v = d.vol < goal ? Math.min(goal, d.vol + step) : Math.max(goal, d.vol - step);
    if (v !== goal) moving = true;
    d.vol = v;
    try {
      d.p.volume = v;
      if (v > 0 && !d.p.playing) d.p.play();
      if (v === 0 && d.p.playing) d.p.pause();
    } catch {}
  }
  if (!moving && timer) { clearInterval(timer); timer = null; }
}
function kick() { if (!timer) timer = setInterval(tick, STEP); tick(); }

/** Which music should be playing: hub for menus, battle or boss in fights, null for none. */
export function setMusic(k: MusicName | null) {
  if (k === want) return;
  want = k;
  kick();
}

/** The Sound and Music switches. */
export function setAudioPrefs(sound: boolean, music: boolean) {
  soundOn = sound;
  if (music !== musicOn) { musicOn = music; kick(); }
}

AppState.addEventListener('change', s => { active = s === 'active'; kick(); });
// A browser refuses audio until the page has been tapped.
if (!unlocked && typeof document !== 'undefined') {
  document.addEventListener('pointerdown', () => { unlocked = true; kick(); }, { once: true, capture: true });
}
